parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "case": {
      "type": "string",
      "enum": ["1", "2", "3", "4"],
      "description": "Il caso determinato in base alla richiesta dell'utente"
    },
    "topic": {
      "type": "string",
      "description": "Argomento ML principale estratto dalla richiesta"
    },
    "dataset_url": {
      "type": "string",
      "description": "URL del dataset Kaggle trovato, costruito da ref come https://www.kaggle.com/datasets/{ref}. Stringa vuota se non applicabile."
    },
    "dataset_name": {
      "type": "string",
      "description": "Nome del dataset Kaggle trovato. Stringa vuota se non applicabile."
    },
    "data_type": {
      "type": "string",
      "enum": ["text", "tabular", "none"],
      "description": "Tipo di dati del dataset trovato. \"none\" se non applicabile."
    },
    "message_to_user": {
      "type": "string",
      "description": "Messaggio in italiano da mostrare in chat, popolato solo per case \"1\". Stringa vuota altrimenti."
    },
    "instance_text": {
      "type": "string",
      "description": "Contenuto concreto per l'inferenza estratto verbatim dal prompt (es. testo email, specifiche fornite). Stringa vuota se il prompt non fornisce alcun dettaglio concreto oltre alla descrizione del task."
    }
  },
  "required": ["case", "topic", "dataset_url", "dataset_name", "data_type", "message_to_user", "instance_text"]
}

parameters.text:
=Target column: {{ $json.output.target_column }}
Task type: {{ $json.output.task_type }}
Instance features: {{ $json.output.instance_features }}
Dataset name: {{ $json.output.dataset_name }}
Owner slug: {{ $json.output.ownerSlug }}
Dataset slug: {{ $json.output.datasetSlug }}
File name: {{ $json.output.fileName }}
Sample size: {{ $json.output.sample_size }}
